oxy_webhelp_navlinks = {"database_backup_customization-d39307e38759":{"topics":[{"title":"Customizing database backups","shortdesc":"<p class=\"shortdesc\">Define default configuration settings to use during backups of a specific Oracle         database or Oracle RAC.<\/p>","href":"oracle\/customizing_database_backups.html","attributes":{"data-id":"customizing_database_backups"},"menu":{"hasChildren":false},"tocID":"customizing_database_backups-d39307e38770","topics":[]},{"title":"Section sizes for Oracle databases","shortdesc":"<p class=\"shortdesc\">You can expedite Oracle database backups by specifying a section size for the         database, which enables the Rubrik cluster to divide database datafiles into multiple         sections and back them up simultaneously.<\/p>","href":"oracle\/section_sizes_for_oracle_databases.html","attributes":{"data-id":"section_sizes_for_oracle_databases"},"menu":{"hasChildren":false},"tocID":"section_sizes_for_oracle_databases-d39307e38781","topics":[]}]}};